2`: the tests that pin the fix. The class Javadoc says it covers the \"create_database_* and create_user_* credentials in scripted setup\" fix.\n6. `openmrs-core/web/src/test/java/org/openmrs/web/filter/initialization/InitializationFilterTest.java:167-168`: a test that sets `CREATE_DATABASE_USERNAME` and `CREATE_DATABASE_PASSWORD` as environment variables.\n7. `openmrs-core/startup-init.sh:140-154`: the container startup script that writes `create_database_user` and the connection properties into the server properties file.\n\n```json\n[\n  {\"path\": \"openmrs-core/web/src/main/java/org/openmrs/web/filter/initialization/InitializationFilter.java\", \"startLine\": 197, \"endLine\": 201},\n  {\"path\": \"openmrs-core/web/src/main/java/org/openmrs/web/filter/initialization/InitializationFilter.java\", \"startLine\": 1948, \"endLine\": 1953},\n  {\"path\": \"openmrs-core/web/src/main/java/org/openmrs/web/filter/initialization/InitializationFilter.java\", \"startLine\": 340, \"endLine\": 343},\n  {\"path\": \"openmrs-core/web/src/main/java/org/openmrs/web/filter/initialization/InitializationFilter.java\", \"startLine\": 370, \"endLine\": 373},\n  {\"path\": \"openmrs-core/web/src/test/java/org/openmrs/web/filter/initialization/InitializationFilterNormalizationTest.java\", \"startLine\": 18, \"endLine\": 82},\n  {\"path\": \"openmrs-core/web/src/test/java/org/openmrs/web/filter/initialization/InitializationFilterTest.java\", \"startLine\": 167, \"endLine\": 168},\n  {\"path\": \"openmrs-core/startup-init.sh\", \"startLine\": 140, \"endLine\": 154}\n]\n```"}],"container":null,"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":2,"cache_creation_input_tokens":554,"cache_read_input_tokens":23745,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":554},"output_tokens":5,"service_tier":"standard","inference_geo":"global","speed":"standard"},"input_transformations":[],"diagnostics":null,"context_management":null},"parent_